commands.command:
.venv/bin/python - <<'PY'
from experiments.train_trm_operator import PerCellTokenRecurrentOperator, TrackBConfig
for hidden in [256,320,384]:
  for nhead in [4,5,6,8]:
    if hidden % nhead:
      continue
    for ff in [2048,3072,4096,6144,8192,10240]:
      model=PerCellTokenRecurrentOperator(TrackBConfig(hidden_dim=hidden,nhead=nhead,feedforward_dim=ff,recurrence_steps=12,dropout=0.0))
      params=sum(p.numel() for p in model.parameters())
      if 5_000_000 <= params <= 8_000_000:
        print({'hidden_dim':hidden,'nhead':nhead,'feedforward_dim':ff,'recurrence_steps':12,'params':params})
PY
